//! Retained negative source lineage; no MLS membership or approval restoration.
use crate::SqliteResultExt;
use cgka_traits::storage::StorageResult;
use rusqlite::Transaction;
pub(crate) fn apply(tx: &Transaction<'_>) -> StorageResult<()> {
    tx.execute_batch("ALTER TABLE mirrored_chat_catalog ADD COLUMN origin_id BLOB;
ALTER TABLE mirrored_chat_catalog ADD COLUMN origin_order INTEGER;
ALTER TABLE mirrored_chat_messages ADD COLUMN origin_id BLOB;
ALTER TABLE mirrored_chat_messages ADD COLUMN origin_order INTEGER;
CREATE TABLE mirrored_chat_origin_fences(account BLOB NOT NULL,local_device BLOB NOT NULL,source_device BLOB NOT NULL,group_id BLOB NOT NULL,origin_id BLOB NOT NULL,origin_order INTEGER NOT NULL,epoch INTEGER NOT NULL,state INTEGER NOT NULL,PRIMARY KEY(account,local_device,source_device,group_id,origin_id),CHECK(length(account)=32 AND length(local_device)=32 AND length(source_device)=32 AND length(group_id) BETWEEN 1 AND 255 AND length(origin_id)=32 AND origin_order BETWEEN 0 AND 8192 AND epoch>=0 AND state IN(1,2)));
CREATE TABLE mirrored_chat_origin_current(account BLOB NOT NULL,local_device BLOB NOT NULL,source_device BLOB NOT NULL,group_id BLOB NOT NULL,origin_id BLOB NOT NULL,origin_order INTEGER NOT NULL,epoch INTEGER NOT NULL,PRIMARY KEY(account,local_device,source_device,group_id),CHECK(length(origin_id)=32 AND origin_order BETWEEN 1 AND 8192 AND epoch>=0));
INSERT OR IGNORE INTO mirrored_chat_origin_fences SELECT s.account,s.local_device,s.source_device,c.group_id,zeroblob(32),0,MAX(json_extract(c.record,'$.source_epoch')),MAX(c.state) FROM mirrored_chat_catalog c JOIN mirrored_chat_scopes s USING(scope) WHERE c.state!=0 GROUP BY s.account,s.local_device,s.source_device,c.group_id;
CREATE TRIGGER mirrored_origin_fence_keep BEFORE DELETE ON mirrored_chat_origin_fences BEGIN SELECT RAISE(ABORT,'source origin fence retained'); END;
CREATE TRIGGER mirrored_origin_fence_update BEFORE UPDATE ON mirrored_chat_origin_fences WHEN NEW.account!=OLD.account OR NEW.local_device!=OLD.local_device OR NEW.source_device!=OLD.source_device OR NEW.group_id!=OLD.group_id OR NEW.origin_id!=OLD.origin_id OR NEW.origin_order!=OLD.origin_order OR NEW.epoch<OLD.epoch OR NEW.state<OLD.state BEGIN SELECT RAISE(ABORT,'source origin fence regressed'); END;
CREATE TRIGGER mirrored_origin_fence_bound BEFORE INSERT ON mirrored_chat_origin_fences WHEN (SELECT count(*) FROM mirrored_chat_origin_fences)>=8192 OR EXISTS(SELECT 1 FROM mirrored_chat_origin_fences f WHERE f.account=NEW.account AND f.local_device=NEW.local_device AND f.source_device=NEW.source_device AND f.group_id=NEW.group_id AND f.origin_id=NEW.origin_id) BEGIN SELECT RAISE(ABORT,'source origin fence limit'); END;
CREATE TRIGGER mirrored_origin_current_keep BEFORE DELETE ON mirrored_chat_origin_current BEGIN SELECT RAISE(ABORT,'source origin observation retained'); END;
CREATE TRIGGER mirrored_origin_current_update BEFORE UPDATE ON mirrored_chat_origin_current WHEN NEW.account!=OLD.account OR NEW.local_device!=OLD.local_device OR NEW.source_device!=OLD.source_device OR NEW.group_id!=OLD.group_id OR NEW.origin_order<OLD.origin_order OR NEW.epoch<OLD.epoch OR (NEW.origin_order=OLD.origin_order AND NEW.origin_id!=OLD.origin_id) BEGIN SELECT RAISE(ABORT,'source origin observation regressed'); END;
CREATE TRIGGER mirrored_origin_current_bound BEFORE INSERT ON mirrored_chat_origin_current WHEN (SELECT count(*) FROM mirrored_chat_origin_current)>=8192 OR EXISTS(SELECT 1 FROM mirrored_chat_origin_current o WHERE o.account=NEW.account AND o.local_device=NEW.local_device AND o.source_device=NEW.source_device AND o.group_id=NEW.group_id) BEGIN SELECT RAISE(ABORT,'source origin observation limit'); END;
CREATE VIEW mirrored_chat_live_catalog AS SELECT c.* FROM mirrored_chat_catalog c JOIN mirrored_chat_scopes s USING(scope) WHERE c.state=0
 AND NOT EXISTS(SELECT 1 FROM mirrored_chat_origin_fences f WHERE f.account=s.account AND f.local_device=s.local_device AND f.source_device=s.source_device AND f.group_id=c.group_id AND (f.state=2 OR f.origin_id=c.origin_id OR (f.origin_order=0 AND (c.origin_id IS NULL OR f.epoch>=json_extract(c.record,'$.source_epoch')))))
 AND ((c.origin_id IS NULL AND NOT EXISTS(SELECT 1 FROM mirrored_chat_origin_current o WHERE o.account=s.account AND o.local_device=s.local_device AND o.source_device=s.source_device AND o.group_id=c.group_id)) OR EXISTS(SELECT 1 FROM mirrored_chat_origin_current o WHERE o.account=s.account AND o.local_device=s.local_device AND o.source_device=s.source_device AND o.group_id=c.group_id AND o.origin_id=c.origin_id AND o.origin_order=c.origin_order));
DROP TRIGGER mirrored_catalog_fence;
DROP TRIGGER mirrored_catalog_bound;
CREATE TRIGGER mirrored_catalog_bound BEFORE INSERT ON mirrored_chat_catalog WHEN (SELECT count(*) FROM mirrored_chat_catalog)>=8192 OR length(NEW.group_id) NOT BETWEEN 1 AND 255 OR (NEW.origin_id IS NULL)!=(NEW.origin_order IS NULL) OR (NEW.origin_id IS NOT NULL AND (length(NEW.origin_id)!=32 OR NEW.origin_order NOT BETWEEN 1 AND 8192)) BEGIN SELECT RAISE(ABORT,'mirrored catalog bound'); END;
CREATE TRIGGER mirrored_catalog_fence BEFORE UPDATE ON mirrored_chat_catalog WHEN NEW.scope!=OLD.scope OR NEW.group_id!=OLD.group_id OR NEW.source_sequence<=OLD.source_sequence OR (NEW.origin_id IS NULL)!=(NEW.origin_order IS NULL) OR (NEW.origin_id IS NOT NULL AND (length(NEW.origin_id)!=32 OR NEW.origin_order NOT BETWEEN 1 AND 8192)) OR (OLD.state!=0 AND NEW.state!=OLD.state AND NOT(OLD.state=1 AND NEW.state=0 AND NEW.origin_id IS NOT NULL AND ((OLD.origin_id IS NOT NULL AND NEW.origin_id!=OLD.origin_id AND NEW.origin_order>OLD.origin_order) OR (OLD.origin_id IS NULL AND json_extract(NEW.record,'$.source_epoch')>json_extract(OLD.record,'$.source_epoch'))))) BEGIN SELECT RAISE(ABORT,'mirrored catalog regression'); END;
CREATE TRIGGER mirrored_catalog_origin_insert AFTER INSERT ON mirrored_chat_catalog WHEN NEW.state=0 AND NOT EXISTS(SELECT 1 FROM mirrored_chat_live_catalog c WHERE c.scope=NEW.scope AND c.group_id=NEW.group_id) BEGIN SELECT RAISE(ABORT,'source lineage refused'); END;
CREATE TRIGGER mirrored_catalog_origin_update AFTER UPDATE ON mirrored_chat_catalog WHEN NEW.state=0 AND NOT EXISTS(SELECT 1 FROM mirrored_chat_live_catalog c WHERE c.scope=NEW.scope AND c.group_id=NEW.group_id) BEGIN SELECT RAISE(ABORT,'source lineage refused'); END;
CREATE TRIGGER mirrored_message_origin_insert BEFORE INSERT ON mirrored_chat_messages WHEN NOT EXISTS(SELECT 1 FROM mirrored_chat_live_catalog c WHERE c.scope=NEW.scope AND c.group_id=NEW.group_id AND c.origin_id IS NEW.origin_id AND c.origin_order IS NEW.origin_order) BEGIN SELECT RAISE(ABORT,'message source lineage refused'); END;
CREATE TRIGGER mirrored_message_origin_update BEFORE UPDATE ON mirrored_chat_messages WHEN (NEW.deleted=0 OR NOT(NEW.origin_id IS OLD.origin_id AND NEW.origin_order IS OLD.origin_order)) AND NOT EXISTS(SELECT 1 FROM mirrored_chat_live_catalog c WHERE c.scope=NEW.scope AND c.group_id=NEW.group_id AND c.origin_id IS NEW.origin_id AND c.origin_order IS NEW.origin_order) BEGIN SELECT RAISE(ABORT,'message source lineage refused'); END;") .storage()
}
